VALUES (NULL, NULL, 332780, 'R.E.P.O.', 'R.E.P.O.', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9lxz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3bwy.jpg', 'R.E.P.O. (Retrieve, Extract and Profit Operation) is an online cooperative survival horror game for up to six players, developed by Swedish studio Semiwork using the Unity engine. Players are tasked with locating valuable physics-based objects within procedurally generated environments and carefully transporting them to extraction points without damaging them, all while avoiding hostile creatures. Between levels, players spend earned currency on permanent upgrades, weapons, and tools at a service station. The game emphasizes verbal coordination and strategic planning among teammates.', 'https://www.igdb.com/games/repo', '["Nintendo Switch 2", "PC (Microsoft Windows)"]', NULL, 7.2, 0, 10.01, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
