VALUES (NULL, NULL, 381245, 'Total War: Warhammer 40,000', 'Total War: Warhammer 40,000', 'game', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob0gs.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4v1x.jpg', 'Experience the brutal fusion of galactic strategy and grimdark warfare in Total War: WARHAMMER 40,000. Take command of iconic factions, customise your war machine, and engage in devastating battles as you carve a bloody warpath across the stars.', 'https://www.igdb.com/games/total-war-warhammer-40000', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, NULL, 0, 1.0629999999999999e+01, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
