VALUES (NULL, NULL, 55029, 'Age of Empires IV', 'Age of Empires IV', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co39tg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar7s2.jpg', 'One of the most beloved real-time strategy games returns to glory with Age of Empires IV, putting you at the center of epic historical battles that shaped the world. Featuring both familiar and innovative new ways to expand your empire in vast landscapes with stunning 4K visual fidelity, Age of Empires IV brings an evolved real-time strategy game to a new generation.', 'https://www.igdb.com/games/age-of-empires-iv', '["PC (Microsoft Windows)"]', NULL, 7.7, 0, 10.01, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
