VALUES (NULL, NULL, 7327, 'Valiant Hearts: The Great War', 'Valiant Hearts: The Great War', 'game', 2014, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co25zo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar8jm.jpg', 'Valiant Hearts: The Great War is the story of 4 crossed destinies and a broken love in a world torn apart. Dive into a 2D animated comic book adventure, mixing exploration, action and puzzles. In Valiant Hearts, the lives of all these characters are inextricably drawn together over the course of the game. Friendship, love, sacrifice and tragedy befall each one as they help each other to retain their humanity against the horrors of war.', 'https://www.igdb.com/games/valiant-hearts-the-great-war', '["PlayStation 3", "PlayStation 4", "Android", "PC (Microsoft Windows)", "iOS", "Xbox 360", "Xbox One", "Nintendo Switch"]', NULL, 7.9, 0, 10.02, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
