VALUES (NULL, NULL, 8036, 'Verdun', 'Verdun', 'game', 2015, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co24l6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6jg.jpg', 'Verdun is the first multiplayer FPS set in a realistic World War One setting, the game which started the 1914-1918 WW1 Game series. The merciless trench warfare offers a unique battlefield experience, immersing you and your squad into intense battles of attack and defense.', 'https://www.igdb.com/games/verdun', '["PlayStation 4", "Linux", "PC (Microsoft Windows)", "PlayStation 5", "Mac", "Xbox One"]', NULL, 5.9, 0, 8.03, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
