VALUES (NULL, NULL, 1384, 'Hotline Miami', 'Hotline Miami', 'game', 2012, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1vqp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar523x.jpg', 'A top-down slasher/shooter with unlockable gameplay-altering masks and weapons, featuring a neon-flavoured electronic aesthetic, in which a hitman receives anonymous calls ordering him to travel to certain residences and crime dens and massacre those within, as he stumbles through unreal visions and inconsistencies without any answers to how, why or who.', 'https://www.igdb.com/games/hotline-miami', '["Google Stadia", "Xbox Series X|S", "PlayStation 3", "PlayStation 4", "Linux", "Android", "PC (Microsoft Windows)", "PlayStation 5", "Mac", "PlayStation Vita", "Xbox One", "Nintendo Switch"]', NULL, 8.5, 0, 11.01, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
