VALUES (NULL, NULL, 559, 'Call of Duty: Modern Warfare 2', 'Call of Duty: Modern Warfare 2', 'game', 2009, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3cwt.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5kzx.jpg', 'Call of Duty: Modern Warfare 2 is a first-person shooter video game developed by Infinity Ward and published by Activision for the Xbox 360 and PlayStation 3 video game consoles and the Microsoft Windows operating system. Officially announced on February 11, 2009, the game was released worldwide on November 10, 2009. It is the sixth installment of the Call of Duty series and the direct sequel to Call of Duty 4: Modern Warfare, continuing the same storyline, with Call of Duty: Modern Warfare 3 set to end the storyline.', 'https://www.igdb.com/games/call-of-duty-modern-warfare-2', '["PlayStation 3", "PC (Microsoft Windows)", "Mac", "Xbox 360"]', NULL, 8.3, 0, 10.11, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
