VALUES (NULL, NULL, 6739, 'Black Mesa', 'Black Mesa', 'game', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co20n4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arft3.jpg', 'Black Mesa is a re-envisioning of Valve Software''s classic science fiction first person shooter, Half-Life. Powered by Source Engine, You will re-visit the inaugural role of Gordon Freeman and his memorable journey through the Black Mesa Research Facility. Expect detailed environments to explore, a huge cast of characters and experimental weaponry. All-new music, voice acting, choreography and added dialogue give way to a more expansive and immersive experience than ever before.', 'https://www.igdb.com/games/black-mesa', '["Linux", "PC (Microsoft Windows)"]', NULL, 8.8, 0, 9.03, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
