VALUES (NULL, NULL, 2538, 'Enslaved: Odyssey to the West', 'Enslaved: Odyssey to the West', 'game', 2010, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coczfb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/e3ety90knwbqzppmeap5.jpg', 'Follow a gripping, surprise-filled journey as two dissimilar characters form an uneasy partnership in order to survive through a perilous, post-apocalyptic America. 150 years in the future, war and destruction have left the world in ruins with few humans remaining and nature having reclaimed the world.', 'https://www.igdb.com/games/enslaved-odyssey-to-the-west', '["PlayStation 3", "PC (Microsoft Windows)", "Xbox 360"]', NULL, 8.1, 0, 10.51, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
