VALUES (NULL, NULL, 9806, 'Hyper Light Drifter', 'Hyper Light Drifter', 'game', 2016, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2edn.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar67f5.jpg', 'Echoes of a dark and violent past resonate throughout a savage land, steeped in treasure and blood. Hyper Light Drifter is an action adventure RPG in the vein of the best 16­-bit classics, with modernized mechanics and designs on a much grander scale.', 'https://www.igdb.com/games/hyper-light-drifter', '["PlayStation 4", "Linux", "PC (Microsoft Windows)", "Mac", "Wii U", "PlayStation Vita", "Xbox One"]', NULL, 8.5, 0, 10.02, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
