VALUES (NULL, NULL, 7642, 'Among the Sleep', 'Among the Sleep', 'game', 2014, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3ywo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1018.jpg', 'Among the Sleep is a first person horror adventure, in which you play a two year old child. After waking up in the middle of the night to mysterious sounds, you start exploring the dark looking for comfort. The game explores horror through atmosphere and exploration, not with scores and combat systems. In Among the Sleep you’re vulnerable, scared, and trying to make sense of the world', 'https://www.igdb.com/games/among-the-sleep', '["PlayStation 4", "Linux", "PC (Microsoft Windows)", "Mac", "Xbox One"]', NULL, 6.8, 0, 1.05, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
