VALUES (NULL, NULL, 424, 'Resident Evil', 'Resident Evil', 'game', 1996, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co20bp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar659t.jpg', 'Resident Evil is a survival horror classic in which a group of special forces agents, known as S.T.A.R.S, struggle against hordes of zombies and various other mutants in a mysterious mansion as they try to uncover the truth behind the terrifying infection. The gameplay environment consists of polygonal 3D characters placed over pre-rendered 2D backgrounds. As such, the game relies on pre-determined camera angles for a view of the action instead of a real-time camera like most games. The game is credited for coining the phrase "survival horror" and popularizing the genre.', 'https://www.igdb.com/games/resident-evil', '["PlayStation"]', NULL, 7.8, 0, 1.04, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
