VALUES (NULL, NULL, 133059, 'Fobia: St. Dinfna Hotel', 'Fobia: St. Dinfna Hotel', 'game', 2022, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4l4i.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1kw9.jpg', 'Fobia: St. Dinfna Hotel is a first-person psychological horror indie game focused on environment exploration, survival and puzzles solving, developed by the Brazilian studio Pulsatrix Studios.', 'https://www.igdb.com/games/fobia-st-dinfna-hotel', '["Xbox Series X|S", "PlayStation 4", "Linux", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 7.5, 0, 1.01, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
