VALUES (NULL, NULL, 329130, 'Ninja Gaiden 4', 'Ninja Gaiden 4', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9b3p.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4k30.jpg', 'The definitive ninja action-adventure franchise returns with Ninja Gaiden 4! Embark on a cutting-edge adventure where legacy meets innovation in a high-octane blend of style and no-holds-barred combat.', 'https://www.igdb.com/games/ninja-gaiden-4', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 7.8, 0, 2.03, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
