VALUES (NULL, NULL, 329132, 'Ninja Gaiden II Black', 'Ninja Gaiden II Black', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9b3s.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar39z5.jpg', 'Using Unreal Engine 5 to significantly enhance graphic expression, this is the definitive version of "NINJA GAIDEN 2," featuring additional playable characters and enhanced battle support functions.', 'https://www.igdb.com/games/ninja-gaiden-ii-black', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 7.5, 0, 1.02, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
