VALUES (NULL, NULL, 98, 'Need for Speed: Most Wanted', 'Need for Speed: Most Wanted', 'game', 2005, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co209j.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4q0l.jpg', 'Need for Speed: Most Wanted is a single-player racing video game and the ninth installment in the Need for Speed series, following Underground 2. The game centers on street-racing gameplay, featuring a variety of events and racing circuits set within the fictional city of Rockport.', 'https://www.igdb.com/games/need-for-speed-most-wanted', '["PC (Microsoft Windows)", "Xbox 360"]', NULL, 8.5, 0, 2.07, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
