VALUES (NULL, NULL, 186725, 'Vampire Survivors', 'Vampire Survivors', 'game', 2022, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4bzv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1cnh.jpg', 'Mow thousands of night creatures and survive until dawn! Vampire Survivors is a gothic horror casual game with rogue-lite elements, where your choices can allow you to quickly snowball against the hundreds of monsters that get thrown at you.', 'https://www.igdb.com/games/vampire-survivors', '["Xbox Series X|S", "PlayStation 4", "Linux", "Android", "PC (Microsoft Windows)", "iOS", "PlayStation 5", "Mac", "Xbox One", "Nintendo Switch"]', NULL, 8.6, 0, 1.05, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
