VALUES (NULL, NULL, 2407, 'Crisis Core: Final Fantasy VII', 'Crisis Core: Final Fantasy VII', 'game', 2007, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1trb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/raiaxap2twvn15rnjml2.jpg', 'In CRISIS CORE, players can experience the D.M.W (Digital Mind Wave) system, which enhances the real-time battle system, allowing players to unleash special attacks or call upon various FINAL FANTASY summons. Players can also witness graphics and CG cutscenes coupled with voice acting in a 16:9 widescreen presentation, made possible by the PSP system hardware.', 'https://www.igdb.com/games/crisis-core-final-fantasy-vii', '["PlayStation Portable"]', NULL, 8.5, 0, 1.02, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
