VALUES (NULL, NULL, 44524, 'Infected', 'Infected', 'game', 2005, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4eqc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scka31.jpg', 'Not your ordinary shooter, Infected lets your avatar invade your opponents'' PSP systems with each of your multiplayer victories. In single-player mode, you play as Stevens, a New York City police officer with immunity to a virus that''s spreading across New York. Only you can stop the virus from spreading by shooting infected individuals with a special "viral gun" that''s loaded with bullets filled with your blood. Eliminate the virus in single-player mode, or use the PSP''s Wi-Fi capabilities to spread your own virus in multiplayer combat.', 'https://www.igdb.com/games/infected', '["PlayStation Portable"]', NULL, NULL, 0, 1.02, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
