VALUES (NULL, NULL, 196655, 'Slayers X: Terminal Aftermath - Vengance of the Slayer', 'Slayers X: Terminal Aftermath - Vengance of the Slayer', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4mud.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1l0c.jpg', 'So.... got what it takes to be a X Slayer?!?... 7 weapons, blood and gore, twisted music by Seepage & Psyko Syndikate, and maps where you can blow up everything. its awesome. started making it in 1998 in high school with my friend and now im 37, so i have life experience now.', 'https://www.igdb.com/games/slayers-x-terminal-aftermath-vengance-of-the-slayer', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One", "Nintendo Switch"]', NULL, 6.5, 0, 1.02, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
