VALUES (NULL, NULL, 134560, 'Metal: Hellsinger', 'Metal: Hellsinger', 'game', 2022, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coan1t.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4ek5.jpg', 'Strike terror into the hearts of demons and devils as you fight your way through eight Hells. Metal: Hellsinger is a rhythm FPS, brimming with diabolical enemies, powerful weapons, and metal music. Set out on an infernal journey in order to achieve the purest of goals: Vengeance.', 'https://www.igdb.com/games/metal-hellsinger', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 8.2, 0, 1.02, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
