VALUES (NULL, NULL, 3249, 'Road Rash', 'Road Rash', 'game', 1991, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5p41.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/jmcjdzp6uf3eiw4vnjg2.jpg', 'Road Rash is a high-octane motorcycle racing game where players become bikers competing in illegal races across the U.S.A. The game focuses on a series of races in California, which players must win to progress to more challenging competitions. Along the way, they engage in both unarmed and armed combat to outmaneuver other racers.', 'https://www.igdb.com/games/road-rash', '["Super Nintendo Entertainment System", "Sega Mega Drive/Genesis", "Atari ST/STE", "Amiga"]', NULL, 6.9, 0, 2.015, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
