VALUES (NULL, NULL, 11, 'Vampire: The Masquerade - Bloodlines', 'Vampire: The Masquerade - Bloodlines', 'game', 2004, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2n14.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4pm0.jpg', 'A first- and third-person Western RPG based on the Vampire: The Masquerade tabletop RPG with a heavy emphasis on character building and role-playing, in which the player embodies a fledgling vampire under the guidance of vampire prince Sebastian LaCroix. The player must serve the prince while getting to know the various factions of vampires in Los Angeles and forming their own political views.', 'https://www.igdb.com/games/vampire-the-masquerade-bloodlines', '["PC (Microsoft Windows)"]', NULL, 7.9, 0, 1.02, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
