VALUES (NULL, NULL, 122666, 'Teardown', 'Teardown', 'game', 2022, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7avn.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arh14.jpg', 'Prepare the perfect heist in this simulated and fully destructible voxel world. Tear down walls with vehicles or explosives to create shortcuts. Stack objects to reach higher. Use the environment to your advantage in the most creative way you can think of.', 'https://www.igdb.com/games/teardown', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 8.2, 0, 1.01, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
