VALUES (NULL, NULL, 102780, 'Beware', 'Beware', 'game', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8j8c.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sckely.jpg', 'Beware is currently in early development. At the base, it''s an open-world driving simulation where the player embarks on a long journey of information-gathering through exploration. One of the gameplay elements are intense, 70''s movies style, car chases with challenging AI opponents. There are stealth element too where you can avoid being detected and explore the world undisturbed.', 'https://www.igdb.com/games/beware', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 2.065, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
