VALUES (NULL, NULL, 7342, 'Inside', 'Inside', 'game', 2016, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2fca.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ard8r.jpg', 'Inside is a puzzle-platformer developed by Playdead, presented in a 2.5D side-scrolling format with a dark, predominantly monochromatic visual style. The player controls an unnamed boy navigating a dystopian environment, solving environmental puzzles, avoiding hostile guards and creatures, and using a mind-control device to manipulate bodies in order to progress. The game features no dialogue or HUD, relying on visual and audio cues to guide the player through its increasingly surreal and dangerous settings.', 'https://www.igdb.com/games/inside', '["PlayStation 4", "PC (Microsoft Windows)", "iOS", "Mac", "Xbox One", "Nintendo Switch"]', NULL, 8.9, 0, 1.01, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
