VALUES (NULL, NULL, 223, 'The Sims', 'The Sims', 'game', 2000, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8j9a.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ary48.jpg', 'The Sims is a life-building simulation with emphasis on intimate details of individual characters rather than expansion of an entire society or civilization. You are in control of nearly every aspect of the lives of the individuals who make up your chosen population in the neighborhood. Characters are developed from the ground up and you infuse and mold them with personalities, looks, desires, moods, urges, living arrangements, career and personal choices, life styles, and reactions.', 'https://www.igdb.com/games/the-sims', '["Linux", "PC (Microsoft Windows)", "Mac"]', NULL, 8.2, 0, 1.06, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
