VALUES (NULL, NULL, 429, 'Call of Juarez', 'Call of Juarez', 'game', 2006, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1qqg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arsde.jpg', 'Call of Juarez is an epic adventure western themed FPS game. The player alternately assumes the roles of two distinct, antagonistic characters: a sneaking fugitive Billy and his hunter the reverend Ray. Apart from the highly interesting, emotional and psychological aspect of the link between the two', 'https://www.igdb.com/games/call-of-juarez', '["PC (Microsoft Windows)", "Xbox 360"]', NULL, 7.4, 0, 9.02333333333333342e+00, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
