VALUES (NULL, NULL, 3262, 'Grand Theft Auto: Vice City Stories', 'Grand Theft Auto: Vice City Stories', 'game', 2006, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2lc8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ig6unih5hvea9aurbd1c.jpg', 'The PlayStation Portable follow-up to Rockstar''s monumental handheld entry in the series, Grand Theft Auto: Liberty City Stories. As in Liberty City Stories, this game ventures back to the location of the second PS2 game.', 'https://www.igdb.com/games/grand-theft-auto-vice-city-stories', '["PlayStation 3", "PlayStation Portable", "PlayStation 2"]', NULL, 7.5, 0, 1.0, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
