VALUES (NULL, NULL, 3270, 'Grand Theft Auto: Chinatown Wars', 'Grand Theft Auto: Chinatown Wars', 'game', 2009, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2lba.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/uc9gnfnqi5egvludf7ls.jpg', 'Grand Theft Auto: Chinatown Wars is an entirely original entry into the critically acclaimed Grand Theft Auto series, and brings a new level of interactivity to its sprawling open environments. With the use of the DS touch screen, players navigate their way through the streets as they uncover the truth behind an epic tale of crime and corruption within the Triad crime syndicate, delivering the unprecedented amount of depth that has become a true trademark of the franchise.', 'https://www.igdb.com/games/grand-theft-auto-chinatown-wars', '["Android", "iOS", "PlayStation Portable", "Nintendo DS"]', NULL, 8.3, 0, 1.0, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
