VALUES (NULL, NULL, 308535, 'NTE: Neverness to Everness', 'NTE: Neverness to Everness', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/codcmk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5sk9.jpg', 'NTE: Neverness to Everness is a supernatural open-world RPG developed by Hotta Studio. The story begins in the city of Hethereau, where you play as its first "unlicensed" Anomaly Hunter. You''ll join the crew at Eibon, a rundown antique shop that keeps the lights on by taking Anomaly commissions from anyone willing to pay. Alongside a diverse cast of extraordinary companions, you''ll unravel urban mysteries, ride out adventures full of laughs and heartbreak, and write your own stories in the neon-lit streets.', 'https://www.igdb.com/games/nte-neverness-to-everness', '["Android", "PC (Microsoft Windows)", "iOS", "PlayStation 5", "Mac"]', NULL, 5.6, 0, 1.01, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
