VALUES (NULL, NULL, 185253, 'Dune: Spice Wars', 'Dune: Spice Wars', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4a96.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1g6w.jpg', 'Dune: Spice Wars is a real-time strategy game with 4X elements, from the developers of the critically acclaimed Northgard. Set in Frank Herbert’s groundbreaking Dune universe, you must lead your faction and battle for control and dominance over the harsh desert planet of Arrakis. Best your opponents through political intrigue, crush them in combat, and undermine them with your network of illusive spies.', 'https://www.igdb.com/games/dune-spice-wars', '["Xbox Series X|S", "PC (Microsoft Windows)"]', NULL, 7.3, 0, 1.01, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
