VALUES (NULL, NULL, 128991, 'Cartel Tycoon', 'Cartel Tycoon', 'game', 2022, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co97wp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar38xj.jpg', 'Cartel Tycoon is a story-driven business sim inspired by the ''80''s narco trade. Expand and conquer, stave off rival cartels and authority attention, earn people''s loyalty and try to overcome the doomed fate of a drug lord with too much power.', 'https://www.igdb.com/games/cartel-tycoon', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 6.2, 0, 1.01, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
