VALUES (NULL, NULL, 6177, 'Stolen', 'Stolen', 'game', 2005, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coc3z6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scjal1.jpg', 'Stolen is a third-person stealth action game in which you play as a female thief. After your everyday job turns sour, you enter a web of conspiracy that threatens to destroy the entire city. With your stealth and agility, you''ll break into and out of various locations (including museums, prisons, and satellite arrays) in an effort to steal priceless items. You''ll have access to different high-tech gadgets and tools that will help you achieve your objectives.', 'https://www.igdb.com/games/stolen', '["Xbox", "PC (Microsoft Windows)", "PlayStation 2"]', NULL, 6.4, 0, 1.01, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
