VALUES (NULL, NULL, 5413, 'Twisted Metal: Black', 'Twisted Metal: Black', 'game', 2001, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1p3q.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5xct.jpg', 'Twisted Metal: Black is a vehicle combat video game developed by Incognito Entertainment (formerly Incog Inc.) and published by Sony Computer Entertainment America for the PlayStation 2 video game console. It is the fifth installment to the Twisted Metal series and was released June 18, 2001. An online enabled multiplayer-only variant, Twisted Metal: Black Online, was released later as a free update.', 'https://www.igdb.com/games/twisted-metal-black', '["PlayStation 3", "PlayStation 4", "PlayStation 2"]', NULL, 8.6, 0, 1.01, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
