VALUES (NULL, NULL, 3332, 'Vigilante 8', 'Vigilante 8', 'game', 1998, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3b83.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5wz7.jpg', 'Vigilante 8 is a vehicular-combat game set in an alternate 1975. Australian terrorist Sid Burn is hired by OMAR to dispose of all competing oil companies in the U.S. so that OMAR can establish an oil monopoly in the country. After hearing reports of destruction by Sid Burn''s gang, the Coyotes, a man named Convoy, a kind-hearted trucker, forms a group of his own, the Vigilantes, to combat the Coyotes and stop the tyranny of OMAR.', 'https://www.igdb.com/games/vigilante-8', '["PlayStation 3", "Nintendo 64", "PlayStation", "PlayStation Portable"]', NULL, 5.7, 0, 1.04, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
