VALUES (NULL, NULL, 8472, 'Gas Guzzlers Extreme', 'Gas Guzzlers Extreme', 'game', 2013, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2d29.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arlc7.jpg', 'Gas Guzzlers Extreme is fast, furious and armed to the teeth: lead-foot-trigger-happy shooter shifted into the 5th gear! It’s a fast-paced addictive combat racing game that features many different vehicles, weapons, upgrades, on-track bonuses as well as distinctive environments.
Players starts with low performance vehicles and gradually works his way up by earning money in a series of challenging races.', 'https://www.igdb.com/games/gas-guzzlers-extreme', '["PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One", "Nintendo Switch"]', NULL, 6.7, 0, 1.02, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
