VALUES (NULL, NULL, 177689, 'Fumes', 'Fumes', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7v0d.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar36qz.jpg', 'Fumes is a single-player game inspired by the golden era of vehicular combat genre. Straight-forward, fast paced, intense gameplay. Get into the car, slap some weapons on and cruise twisted wastes. No bullscrap. Just you, your car and pure fun. Like in the old days!', 'https://www.igdb.com/games/fumes', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 1.03, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
