VALUES (NULL, NULL, 413472, 'Half Grip', 'Half Grip', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cocov1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6ki4.jpg', 'Get hooked on this brutal one-armed rogue-like combat racing game where every action is a gamble. Steer, shoot and reload - each split-second counts as you compete against armed rivals across atmospheric tracks rendered in harsh pixelated detail.', 'https://www.igdb.com/games/half-grip', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 1.01, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
