VALUES (NULL, NULL, 6998, 'Full Auto', 'Full Auto', 'game', 2006, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6px1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sceh9m.jpg', 'Full Auto gives ''gun it'' a whole new meaning. It''s a driving auto combat game in the vein of burnout and twisted metal. You''ll drive through various courses set all over the world in all sorts of different environments and blow stuff up. You''ll go from level to level completing various objectives and trying to get not only a great destruction score but first place to the finish line. If you’re unlucky enough to get blown up by someone, you can always ‘un-wreck’ and turn back the clock to get a second chance and turn the tables. When you’re done wrecking the AI, you can take the road war onto Xbox live where you can race and blowup up to 8 opponents.', 'https://www.igdb.com/games/full-auto', '["Xbox 360"]', NULL, 6.8, 0, 1.01, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
