VALUES (NULL, NULL, 312277, 'Wreckfest 2', 'Wreckfest 2', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8mji.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar32rp.jpg', 'Ready for mayhem? Wreckfest is back, offering the best in full-contact racing with unrivaled destruction! Witness head-to-head battles as you tear apart rival vehicles bit by bit. Powered by the enhanced physics engine, developed by the creators of Wreckfest & FlatOut!', 'https://www.igdb.com/games/wreckfest-2', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, NULL, 0, 1.01, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
