VALUES (NULL, NULL, 66922, 'Metal Max 3', 'Metal Max 3', 'game', 2010, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8l0k.jpg', NULL, 'Metal Max 3 is a nonlinear, open world, turn-based RPG with vehicle combat elements for the Nintendo DS. It was developed by Cattle Call and Crea-Tech, and published by Kadokawa Games and Enterbrain.', 'https://www.igdb.com/games/metal-max-3', '["Nintendo DS"]', NULL, 7.7, 0, 9.01, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
