VALUES (NULL, NULL, 3070, 'Euro Truck Simulator 2', 'Euro Truck Simulator 2', 'game', 2012, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7et5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6z0j.jpg', 'Euro Truck Simulator 2 is a vehicle simulation game and a direct sequel to the 2008 game Euro Truck Simulator. Travel across Europe as king of the road, a trucker who delivers important cargo across impressive distances! With dozens of cities to explore from the UK, Belgium, Germany, Italy, the Netherlands, Poland, and many more, your endurance, skill and speed will all be pushed to their limits. If you’ve got what it takes to be part of an elite trucking force, get behind the wheel and prove it!', 'https://www.igdb.com/games/euro-truck-simulator-2', '["Xbox Series X|S", "PlayStation 4", "Linux", "PC (Microsoft Windows)", "PlayStation 5", "Mac", "Xbox One"]', NULL, 8.3, 0, 9.09, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
