VALUES (NULL, NULL, 11325, 'The Oregon Trail', 'The Oregon Trail', 'game', 1971, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6k5q.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scv9o4.jpg', 'The Oregon Trail is a computer game originally developed by Don Rawitsch, Bill Heinemann, and Paul Dillenberger in 1971 and produced by the Minnesota Educational Computing Consortium (MECC) in 1974. The original game was designed to teach school children about the realities of 19th-century pioneer life on the Oregon Trail. The player assumes the role of a wagon leader guiding his or her party of settlers from Independence, Missouri, to Oregon''s Willamette Valley on the Oregon Trail via a covered wagon in 1848.', 'https://www.igdb.com/games/the-oregon-trail', '["HP 2100", "CDC Cyber 70"]', NULL, 8.2, 0, 6.02, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
