VALUES (NULL, NULL, 361833, 'Valor Mortis', 'Valor Mortis', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaazc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar41b5.jpg', 'Valor Mortis is a first-person action soulslike from the creators of Ghostrunner. Rise from death as a former soldier of Napoleon’s army. Wield supernatural powers, battle horrifying monsters, and unravel a conspiracy that threatens all of humanity.', 'https://www.igdb.com/games/valor-mortis', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 8.2, 0, 7.01, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
