VALUES (NULL, NULL, 398638, 'Corsair Cove', 'Corsair Cove', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobxwd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5qdv.jpg', 'Build a sprawling pirate haven, raise a fleet to explore the high seas, and take on the Crown to keep the Age of Piracy alive! From ale to flintlock pistols, and from scallywags to swashbucklers, you’ll need to manage complex production chains and govern a rowdy crew to reign supreme over the seas!', 'https://www.igdb.com/games/corsair-cove', '["PC (Microsoft Windows)"]', NULL, 6.6, 0, 7.01, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
