VALUES (NULL, NULL, 27092, 'GreedFall', 'GreedFall', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cocsi1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/qrdvshwkob45pa6hkdve.jpg', 'GreedFall is a single-player action RPG set in a fictional world inspired by 17th-century Baroque Europe. Players take the role of a diplomat arriving on a remote island inhabited by natives with supernatural abilities, now contested by colonial factions from various nations. The game emphasizes player choice, offering combat, diplomacy, and stealth approaches to quests, with decisions affecting relationships between the island''s competing factions. A prequel, GreedFall 2: The Dying World, was released in 2026.', 'https://www.igdb.com/games/greedfall', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 7.2, 0, 7.02, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
