VALUES (NULL, NULL, 134706, 'Star Wars: Squadrons', 'Star Wars: Squadrons', 'game', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3wlz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar8fz.jpg', 'Master the art of starfighter combat in the authentic piloting experience STAR WARS: Squadrons. Buckle up, feel the adrenaline of first-person multiplayer space dogfights alongside your squadron, and learn what it means to be a pilot in a thrilling STAR WARS single-player campaign.', 'https://www.igdb.com/games/star-wars-squadrons', '["Xbox Series X|S", "Windows Mixed Reality", "PlayStation 4", "PlayStation VR", "PC (Microsoft Windows)", "SteamVR", "PlayStation 5", "Oculus Rift", "Xbox One"]', NULL, 7.5, 0, 8.02, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
