VALUES (NULL, NULL, 2004, 'Torment: Tides of Numenera', 'Torment: Tides of Numenera', 'game', 2017, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co24ni.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar8j7.jpg', 'Torment: Tides of Numenera is a game set in the world of Monte Cook''s new tabletop RPG setting, Numenera. Torment continues the thematic legacy of Planescape: Torment, the critically acclaimed role-playing game from 1999 that''s considered by many to be a hallmark for storytelling in computer RPGs. With Torment, we''re creating a rich role-playing experience that explores similar deep, personal themes.', 'https://www.igdb.com/games/torment-tides-of-numenera', '["PlayStation 4", "Linux", "PC (Microsoft Windows)", "Mac", "Xbox One"]', NULL, 7.9, 0, 11.035, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
