VALUES (NULL, NULL, 228538, 'Skydance''s Behemoth', 'Skydance''s Behemoth', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8cac.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2zft.jpg', 'Skydance’s Behemoth is an original story set in the Forsaken Lands, a fallen kingdom haunted by tragedy. Play as an outland warrior, Wren the Hunter, and embark on a perilous quest to end the curse that plagues yourself and your village. Your only hope is to slay the unslayable, the monstrous Behemoths.', 'https://www.igdb.com/games/skydances-behemoth', '["Meta Quest 2", "PlayStation VR2", "SteamVR", "Meta Quest 3"]', NULL, 7.0, 0, 9.01, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
