VALUES (NULL, NULL, 5434, 'Shadow of the Beast', 'Shadow of the Beast', 'game', 1989, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2jhy.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2x4q.jpg', 'Shadow of the Beast is a platform game developed by Reflections and published by Psygnosis in 1989. The original version was released for the Amiga and later ported to many other systems. The game was known for its graphics, with many colours on screen and up to twelve levels of parallax scrolling backdrops, and its atmospheric score composed by David Whittaker, which used high-quality instrument samples.', 'https://www.igdb.com/games/shadow-of-the-beast', '["Commodore VIC-20", "Commodore C64/128/MAX", "ZX Spectrum", "Atari Lynx", "Super Nintendo Entertainment System", "Sega Mega Drive/Genesis", "Atari ST/STE", "FM Towns", "Amiga", "Turbografx-16/PC Engine CD", "Amstrad CPC", "Sega Master System/Mark III"]', NULL, 6.9, 0, 8.51, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
