VALUES (NULL, NULL, 14147, 'Jotun: Valhalla Edition', 'Jotun: Valhalla Edition', 'game', 2015, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8lpe.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arr5w.jpg', 'Jotun is a hand-drawn action-exploration game set in Norse mythology. In Jotun, you play Thora, a Norse warrior who has died an inglorious death and must prove herself to the Gods to enter Valhalla.', 'https://www.igdb.com/games/jotun-valhalla-edition--2', '["Google Stadia", "PlayStation 4", "Linux", "PC (Microsoft Windows)", "Mac", "Wii U", "Xbox One", "Nintendo Switch"]', NULL, 8.0, 0, 9.01, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
