VALUES (NULL, NULL, 1976, 'Call of Juarez: Gunslinger', 'Call of Juarez: Gunslinger', 'game', 2013, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coag64.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar88s.jpg', 'From the dust of a gold mine to the dirt of a saloon, Call of Juarez: Gunslinger is a real homage to the Wild West tales. Live the epic and violent journey of a ruthless bounty hunter on the trail of the West’s most notorious outlaws. Blurring the lines between man and myth, this adventure made of memorable encounters unveils the untold truth behind some of the greatest legends of the Old West.', 'https://www.igdb.com/games/call-of-juarez-gunslinger', '["PlayStation 3", "PC (Microsoft Windows)", "Xbox 360", "Nintendo Switch"]', NULL, 7.6, 0, 11.715, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
