VALUES (NULL, NULL, 107218, 'Desperados III', 'Desperados III', 'game', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co51km.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4dn.jpg', 'The Wild West. A place where the law is made by those with a gun in their hands, and is enforced by the henchmen at their command. A place where death is no stranger and the undertakers are working overtime… especially when people start playing Desperados III. This real-time tactics game, developed by German game studio Mimimi Games (Shadow Tactics: Blades Of The Shogun), lets players command a band of Desperados led by fan-favourite gunslinger John Cooper.', 'https://www.igdb.com/games/desperados-iii', '["PlayStation 4", "Linux", "PC (Microsoft Windows)", "Mac", "Xbox One"]', NULL, 8.5, 0, 1.21466666666666665e+01, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
