VALUES (NULL, NULL, 4370, 'Sunset Riders', 'Sunset Riders', 'game', 1991, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2p0v.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/u9nrw9v1eacpq5etbdhb.jpg', 'Sunset Riders is a side-scrolling run and gun video game developed and released by Konami in 1991. It is set in the American Old West, where the players take control of bounty hunters who are seeking the rewards offered for various criminals. Each bad guy has a big reward on his head, and they''re helped by hordes of bandits, gunslingers, and horse thieves, so pack loads of lead.', 'https://www.igdb.com/games/sunset-riders', '["Arcade"]', NULL, 7.9, 0, 9.51, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
