VALUES (NULL, NULL, 69874, 'Town With No Name', 'Town With No Name', 'game', 1992, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9whw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8ys4.jpg', 'A budget Amiga CD title released by On-Line entertainment notable for its low quality in all aspects of its production and presentation.', 'https://www.igdb.com/games/town-with-no-name', '["Commodore CDTV", "DOS"]', NULL, NULL, 0, 9.01, '2026-11-24 04:24:23', '2026-11-24 04:24:23')
