VALUES (NULL, NULL, 1051, 'Mirror''s Edge', 'Mirror''s Edge', 'game', 2008, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5gbw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/psw8fikg72y8xxfskg9r.jpg', 'Mirror''s Edge is a first-person action-adventure game focused on parkour and free-running. Set in a heavily surveilled city, players control Faith, a courier who traverses rooftops using wall-runs, jumps, and slides to deliver sensitive information. The gameplay emphasizes momentum and fluid movement over combat, with a focus on finding the fastest path through urban environments.', 'https://www.igdb.com/games/mirror-s-edge', '["PlayStation 3", "PC (Microsoft Windows)", "Xbox 360"]', NULL, 7.5, 0, 4.85, '2026-11-19 20:56:22', '2026-11-24 04:24:23')
