VALUES (NULL, NULL, 2207, 'Shadow of the Colossus', 'Shadow of the Colossus', 'game', 2005, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1ozz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4q0j.jpg', 'An open-world action/adventure game in which a young wanderer, along with a stolen magical sword and his steed companion, trespasses a cursed land, makes a deal with an ancient being to bring a sacrificial victim back to life, and sets off to fulfill his end of the bargain, which involves tracking down and infiltrating the abodes of sixteen colossi and sacrificing them to achieve his goal.', 'https://www.igdb.com/games/shadow-of-the-colossus', '["PlayStation 2"]', NULL, 8.9, 0, 1.55285714285714284e+01, '2026-11-19 20:56:22', '2026-11-24 04:24:23')
