VALUES (NULL, NULL, 74701, 'Star Wars Jedi: Fallen Order', 'Star Wars Jedi: Fallen Order', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1rbi.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5o7.jpg', 'Star Wars Jedi: Fallen Order is a narratively driven, single-player game puts you in the role of a Jedi Padawan who narrowly escaped the purge of Order 66 following the events of Episode III: Revenge of the Sith. On a quest to rebuild the Jedi Order, you must pick up the pieces of your shattered past to complete your training, develop new powerful Force abilities and master the art of the iconic lightsaber - all while staying one step ahead of the Empire and its deadly Inquisitors.', 'https://www.igdb.com/games/star-wars-jedi-fallen-order', '["Google Stadia", "Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 8.2, 0, 10.025, '2026-11-19 20:56:22', '2026-11-24 04:24:23')
