VALUES (NULL, NULL, 201156, 'Star Wars Jedi: Survivor', 'Star Wars Jedi: Survivor', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5uzk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1qqi.jpg', 'The story of Cal Kestis continues in Star Wars Jedi: Survivor, a third-person, galaxy-spanning, action-adventure game from Respawn Entertainment, developed in collaboration with Lucasfilm Games. This narratively driven, single-player title picks up five years after the events of Star Wars Jedi: Fallen Order and follows Cal’s increasingly desperate fight as the galaxy descends further into darkness. Pushed to the edges of the galaxy by the Empire, Cal will find himself surrounded by threats new and familiar. As one of the last surviving Jedi Knights, Cal is driven to make a stand during the galaxy’s darkest times — but how far is he willing to go to protect himself, his crew, and the legacy of the Jedi Order?', 'https://www.igdb.com/games/star-wars-jedi-survivor', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 8.3, 0, 1.13533333333333335e+01, '2026-11-19 20:56:22', '2026-11-24 04:24:23')
