VALUES (NULL, NULL, 286, 'Quake II', 'Quake II', 'game', 1997, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9bg8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arkd5.jpg', 'Quake II is a first-person shooter video game developed by id Software and published by Activision. It is not a direct sequel to Quake, id decided to revert to an existing trademark when they were unable to agree on a new name that did not violate another company''s trademark.', 'https://www.igdb.com/games/quake-ii', '["Zeebo", "Linux", "PC (Microsoft Windows)", "Mac", "Amiga", "PlayStation", "Xbox 360"]', NULL, 8.3, 0, 3.02333333333333342e+00, '2026-11-19 20:56:22', '2026-11-24 04:24:23')
