VALUES (NULL, NULL, 320734, 'White Knuckle', 'White Knuckle', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9mws.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar366w.jpg', 'White Knuckle is a first person speed climbing game. Ascend through the guts of SUB-STRUCTURE 17 using precision movement mechanics. Sharp reflexes and resource management will take you to the highest peaks under ten thousand meters of concrete and decay.', 'https://www.igdb.com/games/white-knuckle', '["PC (Microsoft Windows)"]', NULL, 8.5, 0, 6.26, '2026-11-19 20:56:22', '2026-11-24 04:24:23')
