VALUES (NULL, NULL, 28489, 'Ready or Not', 'Ready or Not', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cocld8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1bv1.jpg', 'Ready or Not is a tactical first person shooter which places you in the boots of an elite SWAT team, tasked with diffusing hostile situations in intense, claustrophobic environments. It''s set in a nondescript modern America, where an income disparity between the classes have become unsustainable and the country has been plunged into havoc. Bring order to chaos with up to 8 players in cooperative play, battle enemy squads in a close player-vs-player environment, or command AI in a striking single-player mode.', 'https://www.igdb.com/games/ready-or-not', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 8.1, 0, 10.14, '2026-11-19 20:56:22', '2026-11-24 04:24:23')
