VALUES (NULL, NULL, 275070, 'Gray Zone Warfare', 'Gray Zone Warfare', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cocd87.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar686q.jpg', 'Enter a high-stakes PvE-first open-world tactical shooter set on a quarantined Southeast Asian island torn apart by faction warfare. Deploy as an elite operator, fight solo or with your squad to carry out missions, earn reputation, and explore the truth behind the Event igniting the conflict.', 'https://www.igdb.com/games/gray-zone-warfare', '["PC (Microsoft Windows)"]', NULL, 8.1, 0, 2.01, '2026-11-19 20:56:22', '2026-11-24 04:24:23')
