VALUES (NULL, NULL, 90558, 'Satisfactory', 'Satisfactory', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8tfy.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar57j.jpg', 'Satisfactory is a first-person factory simulation game set on an alien planet. Players take the role of a Pioneer, an employee of the megacorporation FICSIT Inc., tasked with harvesting natural resources and constructing increasingly complex automated production lines. The goal is to manufacture components for "Project Assembly," delivered via a space elevator to an orbital platform. The game features a hand-crafted open world spanning approximately 30 square kilometers across multiple biomes, a tiered technology progression system, cooperative multiplayer, and extensive logistics management through conveyor belts, pipelines, and vehicles.', 'https://www.igdb.com/games/satisfactory', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 8.4, 0, 6.51500000000000056e+00, '2026-11-19 20:56:22', '2026-11-24 04:24:23')
