VALUES (NULL, NULL, 76253, 'Devil May Cry 5', 'Devil May Cry 5', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1rb4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/gszwggqaia6o7zntd9gu.jpg', 'Devil May Cry 5 is a brand-new entry in the legendary over-the-top action series Devil May Cry. The game features three playable characters, each with a radically different stylish combat play style as they take on the city overrun with demons. Developed with Capcom’s in-house proprietary RE engine, the series continues to achieve new heights in fidelity with graphics that utilize photorealistic character designs and stunning lighting and environmental effects.', 'https://www.igdb.com/games/devil-may-cry-5', '["PlayStation 4", "Nintendo Switch 2", "PC (Microsoft Windows)", "Xbox One"]', NULL, 8.6, 0, 3.03666666666666662e+00, '2026-11-19 20:56:22', '2026-11-24 04:24:23')
