VALUES (NULL, NULL, 142415, 'Indiana Jones and the Great Circle', 'Indiana Jones and the Great Circle', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7nbc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3qeq.jpg', 'Uncover one of history’s greatest mysteries in Indiana Jones and the Great Circle, a first-person, single-player adventure set between the events of Raiders of the Lost Ark and The Last Crusade. You’ll become the legendary archaeologist in this cinematic action-adventure game from MachineGames, the award-winning studio behind the recent Wolfenstein series, and executive produced by Hall of Fame game designer Todd Howard.', 'https://www.igdb.com/games/indiana-jones-and-the-great-circle', '["Xbox Series X|S", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 8.8, 0, 3.04, '2026-11-19 20:56:22', '2026-11-24 04:24:23')
