VALUES (NULL, NULL, 34894, 'Crossout', 'Crossout', 'game', 2017, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3wid.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arh6o.jpg', 'Crossout - the postapocalyptic MMO action game where you can create a unique design for an armoured vehicle from dozens of parts and then drive it into multiplayer battles raging on land and in the skies alike.', 'https://www.igdb.com/games/crossout', '["PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 6.3, 0, 1.05, '2026-11-19 20:56:22', '2026-11-24 04:24:23')
