VALUES (NULL, NULL, 2126, 'Hotline Miami 2: Wrong Number', 'Hotline Miami 2: Wrong Number', 'game', 2015, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3wf6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6xu.jpg', 'Hotline Miami 2: Wrong Number is the brutal conclusion to the Hotline Miami saga, set against a backdrop of escalating violence and retribution over spilled blood in the original game. Follow the paths of several distinct factions – each with their own questionable methods and uncertain motivations – as unforeseen consequences intersect and reality once again slips back into a brilliant haze of neon and bloodshed.', 'https://www.igdb.com/games/hotline-miami-2-wrong-number', '["Google Stadia", "Xbox Series X|S", "PlayStation 3", "PlayStation 4", "Linux", "PC (Microsoft Windows)", "PlayStation 5", "Mac", "PlayStation Vita", "Xbox One", "Nintendo Switch"]', NULL, 7.5, 0, 1.15133333333333336e+01, '2026-11-21 13:07:40', '2026-11-24 04:24:23')
