VALUES (NULL, NULL, 80468, 'Nier Replicant', 'Nier Replicant', 'game', 2010, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coayqc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar7h2.jpg', 'NieR RepliCant is a Japanese PS3 version of NieR Gestalt with a younger main character. Both games are based in the same world, but differ only in the lead character''s design, relationship with the character of Yonah, and the time in which the game takes place.', 'https://www.igdb.com/games/nier-replicant', '["PlayStation 3"]', NULL, 8.8, 0, 6.01500000000000056e+00, '2026-11-21 13:07:40', '2026-11-24 04:24:23')
