VALUES (NULL, NULL, 488, 'Kane & Lynch 2: Dog Days', 'Kane & Lynch 2: Dog Days', 'game', 2010, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa7yf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/areq2.jpg', 'Kane & Lynch 2: Dog Days is a raw and intense third person shooter designed to take players on an visceral story driven experience, following two of gaming''s most disturbed criminals through the gritty Shanghai underworld. Introducing a new visual experience, the design of Kane & Lynch 2: Dog Days has been inspired by documentary film-makers and the user-generated content era.', 'https://www.igdb.com/games/kane-lynch-2-dog-days', '["PlayStation 3", "PC (Microsoft Windows)", "Xbox 360"]', NULL, 6.8, 0, 5.85333333333333349e+00, '2026-11-21 21:29:28', '2026-11-24 04:24:23')
