VALUES (NULL, NULL, 9608, 'Mount & Blade II: Bannerlord', 'Mount & Blade II: Bannerlord', 'game', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaar4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/argae.jpg', 'Mount & Blade II: Bannerlord is the eagerly awaited sequel to the acclaimed medieval combat simulator and role-playing game Mount & Blade: Warband. Set 200 years before, it expands both the detailed fighting system and the world of Calradia. Bombard mountain fastnesses with siege engines, establish secret criminal empires in the back alleys of cities, or charge into the thick of chaotic battles in your quest for power.', 'https://www.igdb.com/games/mount-and-blade-ii-bannerlord', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 7.9, 0, 6.225, '2026-11-21 21:29:28', '2026-11-24 04:24:23')
