VALUES (NULL, NULL, 38, 'Dead Space 2', 'Dead Space 2', 'game', 2011, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co20xq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/f8q9vbzt2timy54mxmph.jpg', 'Three years after the Necromorph infestation aboard the USS Ishimura, Isaac Clarke awakens from a coma, confused, disoriented, and on a space station called The Sprawl. Just as his health begins to improve, The Sprawl is overrun with even more advanced forms of the alien-zombie hybrids.', 'https://www.igdb.com/games/dead-space-2', '["PlayStation 3", "PC (Microsoft Windows)", "Xbox 360"]', NULL, 8.8, 0, 6.77, '2026-11-21 21:29:28', '2026-11-24 04:24:23')
