VALUES (NULL, NULL, 6230, 'E.Y.E: Divine Cybermancy', 'E.Y.E: Divine Cybermancy', 'game', 2011, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7eny.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arig1.jpg', 'In a dark Cyberpunk world, you (and up to 3 friends) wage war against the all-powerful Federation in this Source-powered FPS/RPG.', 'https://www.igdb.com/games/e-y-e-divine-cybermancy', '["Linux", "PC (Microsoft Windows)"]', NULL, 7.8, 0, 8.90666666666666628e+00, '2026-11-23 03:29:46', '2026-11-24 04:24:23')
