VALUES (NULL, NULL, 319087, 'Pathologic 3', 'Pathologic 3', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob0w6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3kyc.jpg', 'Pathologic 3 is a psychological horror game in which you play Daniil Dankovsky, a rationalist doctor trying to defeat death itself as the same doomed town collapses around him. It is a standalone follow-up to Pathologic 2 and a reimagining of the Bachelor route from the original Pathologic, rather than a direct sequel or prequel. Its major new distinction is time manipulation: the premise remains a 12-day plague crisis, but the Bachelor can revisit and alter key events, reflecting his obsession with control, causality, and conquering death.', 'https://www.igdb.com/games/pathologic-3', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 7.9, 0, 4.54, '2026-11-23 03:29:46', '2026-11-24 04:24:23')
